def bm25(q, d, f, idf, avgdl, k1=1.2, b=0.75):
    s = 0.0
    for t in q:
        s += idf[t] * f(t, d) * (k1 + 1) / (f(t, d) + k1 * (1 - b + b * len(d) / avgdl))
    return s

def av_necessity_reward(correct, audio_only_ok, video_only_ok, lam=0.5):
    # audio_only_ok / video_only_ok：删掉另一模态后是否仍能答对
    both_needed = (not audio_only_ok) and (not video_only_ok)
    shortcut = audio_only_ok or video_only_ok
    return (1.0 if (correct and both_needed) else 0.0) - lam * float(shortcut)

def reuse_score(count, succ):
    # count: 片段规范化后的出现次数; succ: 该片段所在轨迹的平均成功率
    return count * succ

def should_merge(count_a, succ_a, count_b, succ_b, tau):
    merged = reuse_score(count_a + count_b, (succ_a + succ_b) / 2)
    return merged >= tau

