def selective_distill(student_logits, teacher_logits, selected_idx, lam=0.5):
    s = F.log_softmax(student_logits[selected_idx], dim=-1)
    t = F.softmax(teacher_logits[selected_idx], dim=-1)
    return lam * F.kl_div(s, t, reduction='batchmean')

