import numpy as np
def wer(ref, hyp):
    r, h = ref.split(), hyp.split()
    d = np.zeros((len(r)+1, len(h)+1), dtype=int)
    d[:, 0] = range(len(r)+1); d[0, :] = range(len(h)+1)
    for i in range(1, len(r)+1):
        for j in range(1, len(h)+1):
            d[i, j] = min(d[i-1, j]+1, d[i, j-1]+1,
                          d[i-1, j-1] + (r[i-1] != h[j-1]))
    return d[-1, -1] / max(len(r), 1)

import torch

def flow_matching_loss(v_theta, x1, hist):
    x0 = torch.randn_like(x1)   # (语义, 地理, 耗时)
    t = torch.rand(x1.shape[0], 1)
    xt = (1 - t) * x0 + t * x1
    return ((v_theta(xt, t, hist) - (x1 - x0)) ** 2).mean()

def reason_reflect(reasoner, frozen_gen, hist, task, rounds=3):
    rewards = []
    for _ in range(rounds):
        cond = reasoner(hist, task)      # 产出条件
        img = frozen_gen(cond)           # 冻结生成器出图
        r = reward(img, hist, task)      # 个性化奖励
        reasoner.reflect(img, r)         # 反思注入下一轮
        rewards.append(r)
    return sum(rewards) / len(rewards)

