import torch

def sinkhorn(C, a, b, eps=0.05, iters=20):
    K = torch.exp(-C / eps)
    u = torch.ones_like(a)
    for _ in range(iters):
        v = b / (K.t() @ u + 1e-8)
        u = a / (K @ v + 1e-8)
    return torch.diag(u) @ K @ torch.diag(v)

def bsearch(a, x):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] == x:
            return mid
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

