def reflow_loss(v_theta, x0, x1, t):
    # x0: noise, x1: teacher endpoint, t: [B, 1, ...]
    xt = (1 - t) * x0 + t * x1
    target = x1 - x0
    return ((v_theta(xt, t) - target) ** 2).mean()

import torch

def sago(outputs_per_variant, eps=1e-6):
    # outputs_per_variant: [V, B, C] 同一批样本在 V 种表述下的 logits
    p = torch.softmax(outputs_per_variant, dim=-1)
    conf = p.max(dim=-1).values            # [V, B]
    return (conf.std(dim=0) / (conf.mean(dim=0).abs() + eps)).mean()

